export const DEFAULT_MASCOT_ASSET_ID = 'asset-default-mascot';
export const STANDARD_AKARI_MASCOT = Object.freeze({
  name: 'たくどん',
  value: '',
  fg: '#f5a000',
  kind: 'image',
  assetId: DEFAULT_MASCOT_ASSET_ID,
  w: 180,
  h: 180,
});
export const DEFAULT_MASCOT_SHA256 =
  '7f6f2d938d207db2b8b47becbd177d33c2c1adda11aafbefaf96ab4cba74357f';
export const DEFAULT_MASCOT_PNG_BASE64 =
  '';
let DEFAULT_MASCOT_ASSET_RECORD: AssetRecord | null = null;
export function defaultMascotAssetRecord() {
  if (DEFAULT_MASCOT_ASSET_RECORD) return DEFAULT_MASCOT_ASSET_RECORD;
  const bytes = decodeBase64(DEFAULT_MASCOT_PNG_BASE64);
  if (bytes.length !== 5476 || sha256Fallback(bytes) !== DEFAULT_MASCOT_SHA256)
    throw new AkariError('F508', 'あかりに 入って いる キャラクターの 絵が こわれて います。先生に 知らせて ください');
  DEFAULT_MASCOT_ASSET_RECORD = makeImmutableAssetRecord({
    id: DEFAULT_MASCOT_ASSET_ID,
    kind: 'image',
    mime: 'image/png',
    sha256: DEFAULT_MASCOT_SHA256,
    bytes,
    meta: { width: 180, height: 180 },
  });
  return DEFAULT_MASCOT_ASSET_RECORD;
}
export function makeDefaultAssetStore() {
  return new AssetStore([defaultMascotAssetRecord()]);
}
export function withDefaultMascotAsset(project: Project, store: InstanceType<typeof AssetStore>) {
  if (
    !collectReachableAssetIds(project).has(DEFAULT_MASCOT_ASSET_ID) ||
    store.has(DEFAULT_MASCOT_ASSET_ID)
  )
    return store;
  const next = new AssetStore(store.snapshotRefs());
  next.addImmutable(defaultMascotAssetRecord());
  return next;
}
// A text in which each half of a surrogate pair that stands alone is U+FFFD, as UTF-8 writes it.
const LONE_SURROGATE = /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g;
export function wellFormedText(value: string): string {
  return value.replace(LONE_SURROGATE, '\ufffd');
}
// Makes the texts of a work's data (in arrays and plain objects, keys too) well formed in the data itself; answers the
// value that stands for the one given (a text's well formed text, anything else as it is).
function wellFormedInPlace(value: unknown): unknown {
  if (typeof value === 'string') return wellFormedText(value);
  if (Array.isArray(value)) {
    value.forEach((item, at) => { value[at] = wellFormedInPlace(item); });
    return value;
  }
  // (a plain object of any realm: its prototype is null or has none)
  if (value === null || typeof value !== 'object') return value;
  const proto: object | null = Object.getPrototypeOf(value);
  if (proto !== null && Object.getPrototypeOf(proto) !== null) return value;
  // (keys keep their order: when a key changes, every key is put again in the order it had)
  const entries = Object.entries(value);
  if (entries.some(([key]) => key !== wellFormedText(key))) for (const [key] of entries) Reflect.deleteProperty(value, key);
  for (const [key, item] of entries)
    Object.defineProperty(value, wellFormedText(key), { value: wellFormedInPlace(item), writable: true, enumerable: true, configurable: true });
  return value;
}
// The data given, every text in it made well formed (the data is a copy that nothing else holds).
export function madeWellFormed<T>(copy: T): T {
  wellFormedInPlace(copy);
  return copy;
}
// A copy of a work's data in which every text is well formed: the file's text and the data in it then say the same, and
// the file opens. Data that cannot be copied is not a work's data: it is answered as it is, and the save refuses it.
export function wellFormedCopy<T>(value: T): T {
  try {
    return madeWellFormed(structuredClone(value));
  } catch (error) {
    if (typeof error === 'object' && error !== null && 'name' in error && error.name === 'DataCloneError') return value; // (of any realm)
    throw error;
  }
}

